do $$ begin if not exists (select 1 from pg_constraint where conname='reconciliation_items_transaction_tenant_fk') then alter table public.reconciliation_items add constraint reconciliation_items_transaction_tenant_fk foreign key (transaction_id,user_id) references public.gateway_transactions(id,user_id); end if; end $$; create index if not exists idx_reconciliation_items_tenant_transaction on public.reconciliation_items(user_id,transaction_id); create index if not exists idx_gateway_payment_token_links_tenant_instrument on public.gateway_payment_token_links(user_id,instrument_id);